const err = $input.item.json;

const execution = err.execution || {};
const workflow = err.workflow || {};
const executionError = execution.error || {};
const trigger = err.trigger || {};
const triggerError = trigger.error || {};

function sanitize(v) {
  if (v === null || v === undefined) return '';

  if (typeof v === 'object') {
    return JSON.stringify(v).replace(
      /(secret|token|password|api[_ -]?key|authorization|bearer)(["']?\s*[:=]\s*)([^,}"'\s]+)/gi,
      '$1$2[REDACTED]'
    );
  }

  return String(v);
}

const errorMessage = String(
  executionError.message ||
  triggerError.message ||
  'unknown error'
).slice(0, 2000);

const node =
  execution.lastNodeExecuted ||
  triggerError.node?.name ||
  triggerError.node ||
  '';

const executionId = execution.id || '';

const workflowName =
  workflow.name ||
  'unknown_workflow';

const workflowId =
  workflow.id ||
  '';

return [{
  json: {
    error_id:
      'err_' +
      Date.now() +
      '_' +
      Math.random().toString(36).slice(2, 8),

    created_at: new Date().toISOString(),

    workflow: workflowName,

    workflow_id: workflowId,

    node: String(node),

    business_id: '',

    lead_id: '',

    error_message: errorMessage,

    execution_id: executionId,

    execution_url: execution.url || '',

    payload: sanitize(err).slice(0, 4000),

    resolved: false
  }
}];
